INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4774494, 688205, 93927, '<td valign="top">Hmm... I wonder who took this. You know this will do well.</td>', 'Hmm... I wonder who took this. You know this will do well.', '2008-06-18 11:19:44.000000', NULL, 1),
(4774514, 689692, 54645, '<td valign="top">Lovely smiles. I like the soft focus. Maybe they could be closer together. The flash cast a terrible shadow, and overall the image is too dark and flat. If you want an unsolicited suggestion, I''ve found that the omnibounce diffuser works great for this type of shot, i.e. for folks without fancy lights, like me. You need a real flash though, I suspect this is the on board flash. Also, move the young ladies further away from the backdrop.</td>', 'Lovely smiles. I like the soft focus. Maybe they could be closer together. The flash cast a terrible shadow, and overall the image is too dark and flat. If you want an unsolicited suggestion, I''ve found that the omnibounce diffuser works great for this type of shot, i.e. for folks without fancy lights, like me. You need a real flash though, I suspect this is the on board flash. Also, move the young ladies further away from the backdrop.', '2008-06-18 11:29:25.000000', NULL, 1),
(4774611, 689262, 93714, '<td valign="top">Lots of grit, good story... 8</td>', 'Lots of grit, good story... 8', '2008-06-18 12:33:36.000000', NULL, 1),
