(4775047, 689702, 20577, '<td valign="top">Beautiful...</td>', 'Beautiful...', '2008-06-18 16:47:30.000000', NULL, 1),
(4775078, 689558, 14867, '<td valign="top">Very interesting.<br/>The harsh light and extreme contrast would probably not work for a single portrait, but build really the composition here - and create between them an  esthetic connection beyond their resemblance.<br/>Their eyes are just a bit too dark, and therefore with less expression, but it''s still a great job!</td>', 'Very interesting.The harsh light and extreme contrast would probably not work for a single portrait, but build really the composition here - and create between them an  esthetic connection beyond their resemblance.Their eyes are just a bit too dark, and therefore with less expression, but it''s still a great job!', '2008-06-18 17:09:15.000000', NULL, 1),
(4775085, 689737, 58457, '<td valign="top">I think this might be more intimate if it were cropped tighter</td>', 'I think this might be more intimate if it were cropped tighter', '2008-06-18 17:12:41.000000', NULL, 1),
(4775089, 688008, 58457, '<td valign="top">very sharp and nice expressions but so small!  I''d like to see this bigger for more impact!</td>', 'very sharp and nice expressions but so small!  I''d like to see this bigger for more impact!', '2008-06-18 17:15:15.000000', NULL, 1),
(4775134, 689302, 58457, '<td valign="top">nice environmental portrait style.  I wish I could see more of the guy at the anvil and the horse''s rear end not so centered and right towards me (its the first thing i see)</td>', 'nice environmental portrait style.  I wish I could see more of the guy at the anvil and the horse''s rear end not so centered and right towards me (its the first thing i see)', '2008-06-18 17:45:24.000000', NULL, 1),
