(4776027, 689706, 83934, '<td valign="top">I like the colors. quite retro. exposed perfectly.</td>', 'I like the colors. quite retro. exposed perfectly.', '2008-06-19 09:55:22.000000', NULL, 1),
(4776029, 688548, 49954, '<td valign="top">Being a parent is a privilege, not a "right".</td>', 'Being a parent is a privilege, not a "right".', '2008-06-19 09:57:02.000000', NULL, 1),
(4776035, 689470, 83934, '<td valign="top">alright studio pic. could use some cropping. Drop the studio lights down to about 3 feet or so to capture the life in their eyes. A little hair light would give this pic a great glow.</td>', 'alright studio pic. could use some cropping. Drop the studio lights down to about 3 feet or so to capture the life in their eyes. A little hair light would give this pic a great glow.', '2008-06-19 09:57:50.000000', NULL, 1),
(4776037, 689727, 83934, '<td valign="top">quite sassy. a little cropping and sharpening would be good</td>', 'quite sassy. a little cropping and sharpening would be good', '2008-06-19 09:58:41.000000', NULL, 1),
(4776038, 689457, 49954, '<td valign="top">They look like sisters!  But processing too harsh.</td>', 'They look like sisters!  But processing too harsh.', '2008-06-19 09:58:43.000000', NULL, 1);
