(4778675, 689626, 93565, '<td valign="top">The baby''s expression is great. I really like the lighting as well.</td>', 'The baby''s expression is great. I really like the lighting as well.', '2008-06-20 23:39:18.000000', NULL, 1),
(4778686, 689798, 82064, '<td valign="top">Very cute!</td>', 'Very cute!', '2008-06-20 23:43:56.000000', NULL, 1),
(4778708, 689781, 93565, '<td valign="top">Bit dark for me, but nice otherwise.</td>', 'Bit dark for me, but nice otherwise.', '2008-06-20 23:58:58.000000', NULL, 1),
(4778718, 688797, 93565, '<td valign="top">Good candid, but the background is a bit distracting</td>', 'Good candid, but the background is a bit distracting', '2008-06-21 00:06:09.000000', NULL, 1),
(4778721, 689766, 93565, '<td valign="top">It looks as though the woman is a little bit out of the DoF.</td>', 'It looks as though the woman is a little bit out of the DoF.', '2008-06-21 00:08:38.000000', NULL, 1),
(4778723, 688548, 93565, '<td valign="top">The expression of joy is great and conveys your title perfectly.</td>', 'The expression of joy is great and conveys your title perfectly.', '2008-06-21 00:09:56.000000', NULL, 1),
(4778728, 689755, 93565, '<td valign="top">I personally don''t appreciate the grain for this application, and the character of the event might have been better captured by emphasizing on the face more.</td>', 'I personally don''t appreciate the grain for this application, and the character of the event might have been better captured by emphasizing on the face more.', '2008-06-21 00:14:13.000000', NULL, 1),
(4778729, 689534, 76335, '<td valign="top">This is just terrific. Technically it''s got some problems, but the composition itself and the capture of emotion is priceless. What a fun image! An <strike>eight</strike> nine for you.</td>', 'This is just terrific. Technically it''s got some problems, but the composition itself and the capture of emotion is priceless. What a fun image! An eight nine for you.', '2008-06-21 00:15:15.000000', NULL, 1),
(4778731, 689702, 93565, '<td valign="top">Very dramatic- the setting is great and I really like the subtlety of the lighting and scene.</td>', 'Very dramatic- the setting is great and I really like the subtlety of the lighting and scene.', '2008-06-21 00:16:19.000000', NULL, 1);
