(4781002, 689803, 79357, '<td valign="top">Too much sharpening added</td>', 'Too much sharpening added', '2008-06-23 03:42:01.000000', NULL, 1),
(4781034, 689755, 39830, '<td valign="top">If it wasn''t for the cell phone and the full frame focus, I could almost believe this Scott Cunningham''s work. Very nicely done. I love the way you used grain to enhance the image.</td>', 'If it wasn''t for the cell phone and the full frame focus, I could almost believe this Scott Cunningham''s work. Very nicely done. I love the way you used grain to enhance the image.', '2008-06-23 04:18:36.000000', NULL, 1),
(4781036, 689798, 39830, '<td valign="top">The title lacks pop, but the photo has it in spades. Very nicely done... 9</td>', 'The title lacks pop, but the photo has it in spades. Very nicely done... 9', '2008-06-23 04:21:23.000000', NULL, 1),
(4781452, 689702, 67585, '<td valign="top">Very well done. Black and white was a good choice for this.</td>', 'Very well done. Black and white was a good choice for this.', '2008-06-23 11:29:56.000000', NULL, 1),
(4781456, 689244, 67585, '<td valign="top">Great natural, candid expressions on both people.  This is a fun shot.</td>', 'Great natural, candid expressions on both people.  This is a fun shot.', '2008-06-23 11:32:13.000000', NULL, 1),
(4781608, 689748, 94306, '<td valign="top">very unique take! love the juxtaposition of real dog and dog mask.</td>', 'very unique take! love the juxtaposition of real dog and dog mask.', '2008-06-23 13:58:15.000000', NULL, 1),
